# Surah Al-A'raf (chapter 7) — part 15: ayat 145-154 (IDs 1099-1108)
SURAH = 7

ENTRIES = {
1099: (
"اور ہم — نے — موسیٰؑ — کے لیے — تختیوں میں — ہر — چیز — کا حکم — اور نصیحت — اور تفصیل — ہر — چیز کی — لکھی — پس — انہیں — مضبوطی کے ساتھ پکڑ — اور اپنی قوم کو — حکم دے — کہ وہ — اس — میں سے — بہترین — کو اپنائیں — عنقریب — میں — تمہیں — فاسقوں کی بستی — دکھاؤں گا",
"""۱۔ تورات کی تختیاں — ہر چیز کی تفصیل۔
۲۔ ’’وَكَتَبْنَا لَهُ فِي الْأَلْوَاحِ مِن كُلِّ شَيْءٍ مَّوْعِظَۃً وَتَفْصِيلًا لِّكُلِّ شَيْءٍ فَخُذْهَا بِقُوَّۃٍ وَأْمُرْ قَوْمَكَ يَأْخُذُوا بِأَحْسَنِهَا سَأُرِيكُمْ دَارَ الْفَاسِقِينَ‘‘ — اور ہم — نے — موسیٰؑ — کے لیے — تختیوں میں — ہر — چیز — کا حکم — اور نصیحت — اور تفصیل — ہر — چیز کی — لکھی — پس — انہیں — مضبوطی کے ساتھ پکڑ — اور اپنی قوم کو — حکم دے — کہ وہ — اس — میں سے — بہترین — کو اپنائیں — عنقریب — میں — تمہیں — فاسقوں کی بستی — دکھاؤں گا — یعنی تختیوں میں — ہر چیز کا حکم — تفصیل سے — موجود تھا۔
۳۔ عملی سبق: اللہ کے احکام — مضبوطی کے ساتھ اپناؤ۔"""
),
1100: (
"عنقریب — میں — زمین میں — ناحق — تکبر کرنے والوں کو — اپنی — نشانیوں سے — ہٹا دوں گا — اور — اگر — وہ — ہر — نشانی دیکھیں — ایمان نہ لائیں — اور — اگر — وہ — ہدایت کا راستہ دیکھیں — اسے راستہ نہ بنائیں — اور — اگر — وہ — گمراہی کا راستہ دیکھیں — اسے راستہ بنا لیں — یہ — اس لیے کہ انہوں نے — ہماری آیات کو جھٹلایا — اور — ان سے — غافل تھے",
"""۱۔ ناحق تکبر — ہدایت سے محرومی کا سبب۔
۲۔ ’’سَأَصْرِفُ عَنْ آيَاتِيَ الَّذِينَ يَتَكَبَّرُونَ فِي الْأَرْضِ بِغَيْرِ الْحَقِّ وَإِن يَرَوْا كُلَّ آيَۃٍ لَّا يُؤْمِنُوا بِهَا وَإِن يَرَوْا سَبِيلَ الرُّشْدِ لَا يَتَّخِذُوهُ سَبِيلًا وَإِن يَرَوْا سَبِيلَ الْغَيِّ يَتَّخِذُوهُ سَبِيلًا ذَٰلِكَ بِأَنَّهُمْ كَذَّبُوا بِآيَاتِنَا وَكَانُوا عَنْهَا غَافِلِينَ‘‘ — عنقریب — میں — زمین میں — ناحق — تکبر کرنے والوں کو — اپنی — نشانیوں سے — ہٹا دوں گا — اور — اگر — وہ — ہر — نشانی دیکھیں — ایمان نہ لائیں — اور — اگر — وہ — ہدایت کا راستہ دیکھیں — اسے راستہ نہ بنائیں — اور — اگر — وہ — گمراہی کا راستہ دیکھیں — اسے راستہ بنا لیں — یہ — اس لیے کہ انہوں نے — ہماری آیات کو جھٹلایا — اور — ان سے — غافل تھے — یعنی تکبر — انسان کو — حق دیکھنے سے محروم کر دیتا ہے۔
۳۔ عملی سبق: تکبر — ہدایت کا سب سے بڑا دشمن ہے۔"""
),
1101: (
"اور جنہوں نے — ہماری آیات — اور آخرت کی ملاقات — کو جھٹلایا — ان کے اعمال — ضائع ہو گئے — کیا — انہیں — اس کے علاوہ — کچھ جزا ملے گی — جو — وہ کرتے تھے",
"""۱۔ آیات و آخرت کا انکار — اعمال کی بربادی۔
۲۔ ’’وَالَّذِينَ كَذَّبُوا بِآيَاتِنَا وَلِقَاءِ الْآخِرَۃِ حَبِطَتْ أَعْمَالُهُمْ هَلْ يُجْزَوْنَ إِلَّا مَا كَانُوا يَعْمَلُونَ‘‘ — اور جنہوں نے — ہماری آیات — اور آخرت کی ملاقات — کو جھٹلایا — ان کے اعمال — ضائع ہو گئے — کیا — انہیں — اس کے علاوہ — کچھ جزا ملے گی — جو — وہ کرتے تھے — یعنی کفر و تکذیب — تمام اعمال — باطل کر دیتی ہے۔
۳۔ عملی سبق: ایمان کے بغیر عمل — ضائع ہو جاتا ہے۔"""
),
1102: (
"اور موسیٰؑ کی قوم — نے — ان کے بعد — اپنے زیورات سے — ایک بچھڑا — بنایا — ایک جسم — جس سے آواز آتی تھی — کیا — وہ نہیں دیکھتے — کہ — وہ — ان سے بات نہیں کرتا — اور — نہ — انہیں — راستہ دکھاتا — انہوں نے — اسے — بنایا — اور — وہ — ظالم تھے",
"""۱۔ بنی اسرائیل — موسیٰؑ کی غیر موجودگی میں — سونے کے بچھڑے کی پوجا۔
۲۔ ’’وَاتَّخَذَ قَوْمُ مُوسَىٰ مِن بَعْدِهِ مِنْ حُلِيِّهِمْ عِجْلًا جَسَدًا لَّهُ خُوَارٌ أَلَمْ يَرَوْا أَنَّهُ لَا يُكَلِّمُهُمْ وَلَا يَهْدِيهِمْ سَبِيلًا اتَّخَذُوهُ وَكَانُوا ظَالِمِينَ‘‘ — اور موسیٰؑ کی قوم — نے — ان کے بعد — اپنے زیورات سے — ایک بچھڑا — بنایا — ایک جسم — جس سے آواز آتی تھی — کیا — وہ نہیں دیکھتے — کہ — وہ — ان سے بات نہیں کرتا — اور — نہ — انہیں — راستہ دکھاتا — انہوں نے — اسے — بنایا — اور — وہ — ظالم تھے — یعنی سونے کا بچھڑا — سب سے مشہور گمراہی ہے — بغیر دلیل اور — بغیر صلاحیت کے معبود بنانا۔
۳۔ عملی سبق: بغیر اللہ کے — کسی کو معبود بنانا — ظلم ہے۔"""
),
1103: (
"اور — جب — ان کے ہاتھ — ان پر پڑ گئے — اور — انہیں — معلوم ہوا کہ — وہ — گمراہ ہو گئے — تو کہا — اگر — ہمارا رب — ہم پر رحم نہ کرے — اور — ہمیں نہ بخشے — تو ہم — ضرور — نقصان پانے والوں میں سے ہو جائیں گے",
"""۱۔ بنی اسرائیل — اپنی گمراہی کا احساس کر کے — توبہ کرتے ہیں۔
۲۔ ’’وَلَمَّا سُقِطَ فِي أَيْدِيهِمْ وَرَأَوْا أَنَّهُمْ قَدْ ضَلُّوا قَالُوا لَئِن لَّمْ يَرْحَمْنَا رَبُّنَا وَيَغْفِرْ لَنَا لَنَكُونَنَّ مِنَ الْخَاسِرِينَ‘‘ — اور — جب — ان کے ہاتھ — ان پر پڑ گئے — اور — انہیں — معلوم ہوا کہ — وہ — گمراہ ہو گئے — تو کہا — اگر — ہمارا رب — ہم پر رحم نہ کرے — اور — ہمیں نہ بخشے — تو ہم — ضرور — نقصان پانے والوں میں سے ہو جائیں گے — یعنی بنی اسرائیل — بچھڑے کی پوجا کے بعد — پشیمان ہوئے اور — توبہ کی۔
۳۔ عملی سبق: گمراہی کا احساس — توبہ کا دروازہ — کھولتا ہے۔"""
),
1104: (
"اور — جب — موسیٰؑ — واپس — اپنی قوم کی طرف — غصے اور اداسی کے ساتھ — آئے — تو کہا — میرے بعد — تو نے — میری کتنی بری جانشینی کی — کیا — تم نے — اپنے رب کے حکم میں — جلدی کی — اور — انہوں نے — تختیاں — پھینک دیں — اور — اپنے بھائی — کا سر — پکڑ کر — اسے — اپنی طرف — کھینچنے لگے — ہارونؑ نے کہا — اے ماں کے بیٹے — بے شک — یہ قوم — نے — مجھے کمزور کر دیا — اور — وہ میرے قریب — قتل تک پہنچ گئے — پس — مجھ پر — دشمنوں کو خوش نہ کر — اور — مجھے — ظالموں کے ساتھ — شامل نہ کر",
"""۱۔ موسیٰؑ — غصے میں — لوٹتے ہیں؛ ہارونؑ خود کو — بے گناہ ثابت کرتے ہیں۔
۲۔ ’’وَلَمَّا رَجَعَ مُوسَىٰ إِلَىٰ قَوْمِهِ غَضْبَانَ أَسِفًا قَالَ بِئْسَمَا خَلَفْتُمُونِي مِن بَعْدِي أَعَجِلْتُمْ أَمْرَ رَبِّكُمْ وَأَلْقَى الْأَلْوَاحَ وَأَخَذَ بِرَأْسِ أَخِيهِ يَجُرُّهُ إِلَيْهِ قَالَ ابْنَ أُمَّ إِنَّ الْقَوْمَ اسْتَضْعَفُونِي وَكَادُوا يَقْتُلُونَنِي فَلَا تُشْمِتْ بِيَ الْأَعْدَاءَ وَلَا تَجْعَلْنِي مَعَ الْقَوْمِ الظَّالِمِينَ‘‘ — اور — جب — موسیٰؑ — واپس — اپنی قوم کی طرف — غصے اور اداسی کے ساتھ — آئے — تو کہا — میرے بعد — تو نے — میری کتنی بری جانشینی کی — کیا — تم نے — اپنے رب کے حکم میں — جلدی کی — اور — انہوں نے — تختیاں — پھینک دیں — اور — اپنے بھائی — کا سر — پکڑ کر — اسے — اپنی طرف — کھینچنے لگے — ہارونؑ نے کہا — اے ماں کے بیٹے — بے شک — یہ قوم — نے — مجھے کمزور کر دیا — اور — وہ میرے قریب — قتل تک پہنچ گئے — پس — مجھ پر — دشمنوں کو خوش نہ کر — اور — مجھے — ظالموں کے ساتھ — شامل نہ کر — یعنی موسیٰؑ — اپنی قوم کے بچھڑے کی پوجا دیکھ کر — سخت ناراض ہوتے ہیں۔
۳۔ شیعہ تفسیر میں ہارونؑ — معصوم نبی ہیں؛ انہوں نے — بچھڑے کی پوجا نہیں روکی کیونکہ قوم انہیں بے کیف بنا چکی تھی۔
۴۔ عملی سبق: غصے میں — پہلے — صورتحال سمجھو؛ پھر — فیصلہ کرو۔"""
),
1105: (
"موسیٰؑ نے کہا — اے میرے رب — مجھے — اور میرے بھائی — کو — بخش دے — اور — ہمیں — اپنی رحمت میں — داخل کر — اور — تو — سب سے زیادہ — رحم کرنے والا ہے",
"""۱۔ موسیٰؑ — اپنے اور ہارونؑ — دونوں کے لیے دعا مانگتے ہیں۔
۲۔ ’’قَالَ رَبِّ اغْفِرْ لِي وَلِأَخِي وَأَدْخِلْنَا فِي رَحْمَتِكَ وَأَنتَ أَرْحَمُ الرَّاحِمِينَ‘‘ — موسیٰؑ نے کہا — اے میرے رب — مجھے — اور میرے بھائی — کو — بخش دے — اور — ہمیں — اپنی رحمت میں — داخل کر — اور — تو — سب سے زیادہ — رحم کرنے والا ہے — یعنی موسیٰؑ — فوری طور پر — اپنے غصے — کو چھوڑ کر — توبہ اور دعا کرتے ہیں۔
۳۔ عملی سبق: غصے کے بعد — فوراً — توبہ اور دعا کرو۔"""
),
1106: (
"بے شک — جنہوں نے — بچھڑا — بنایا — ان پر — عنقریب — ان کے رب کی طرف سے — غضب — اور ذلت — دنیا کی زندگی میں — آئے گی — اور — ہم — اسی طرح — جھوٹ گھڑنے والوں کو — جزا دیتے ہیں",
"""۱۔ بچھڑے والوں پر — غضب اور ذلت۔
۲۔ ’’إِنَّ الَّذِينَ اتَّخَذُوا الْعِجْلَ سَيَنَالُهُمْ غَضَبٌ مِّن رَّبِّهِمْ وَذِلَّۃٌ فِي الْحَيَاۃِ الدُّنْيَا وَكَذَٰلِكَ نَجْزِي الْمُفْتَرِينَ‘‘ — بے شک — جنہوں نے — بچھڑا — بنایا — ان پر — عنقریب — ان کے رب کی طرف سے — غضب — اور ذلت — دنیا کی زندگی میں — آئے گی — اور — ہم — اسی طرح — جھوٹ گھڑنے والوں کو — جزا دیتے ہیں — یعنی بچھڑے کی پوجا کا نتیجہ — غضب اور ذلت ہے۔
۳۔ عملی سبق: بدعت — اور خود تراشی — اللہ کی خاص سزا ہے۔"""
),
1107: (
"اور جنہوں نے — گناہ — کئے — پھر — ان — کے بعد — توبہ کی — اور ایمان لائے — بے شک — تمہارا رب — اس کے بعد — ضرور — بخشنے والا — رحم کرنے والا ہے",
"""۱۔ توبہ — سب کے لیے — دروازہ کھلا ہے۔
۲۔ ’’وَالَّذِينَ عَمِلُوا السَّيِّئَاتِ ثُمَّ تَابُوا مِن بَعْدِهَا وَآمَنُوا إِنَّ رَبَّكَ مِن بَعْدِهَا لَغَفُورٌ رَّحِيمٌ‘‘ — اور جنہوں نے — گناہ — کئے — پھر — ان — کے بعد — توبہ کی — اور ایمان لائے — بے شک — تمہارا رب — اس کے بعد — ضرور — بخشنے والا — رحم کرنے والا ہے — یعنی گناہ کے بعد بھی — سچی توبہ — اللہ کی بخشش کا سبب ہے۔
۳۔ عملی سبق: توبہ — کبھی دیر سے نہیں ہوتی؛ ابھی کرو۔"""
),
1108: (
"اور — جب — موسیٰؑ — کا غصہ — ٹھنڈا ہوا — تو — انہوں نے تختیاں — اٹھائیں — اور — ان — کی — لکھائی میں — ہدایت اور رحمت تھی — ان لوگوں کے لیے — جو — اپنے رب سے — ڈرتے ہیں",
"""۱۔ موسیٰؑ — غصہ ٹھنڈا ہونے کے بعد — تختیاں اٹھاتے ہیں۔
۲۔ ’’وَلَمَّا سَكَتَ عَن مُّوسَى الْغَضَبُ أَخَذَ الْأَلْوَاحَ وَفِي نُسْخَتِهَا هُدًى وَرَحْمَۃٌ لِّلَّذِينَ هُمْ لِرَبِّهِمْ يَرْهَبُونَ‘‘ — اور — جب — موسیٰؑ — کا غصہ — ٹھنڈا ہوا — تو — انہوں نے تختیاں — اٹھائیں — اور — ان — کی — لکھائی میں — ہدایت اور رحمت تھی — ان لوگوں کے لیے — جو — اپنے رب سے — ڈرتے ہیں — یعنی تختیاں — ہدایت اور رحمت کا خزانہ — ہیں — بمقابلہ بچھڑے کے باطل — نشان کے۔
۳۔ عملی سبق: غصہ — ٹھنڈا ہونے پر — اللہ کی ہدایت سے — مستفید ہو — کرو۔"""
),
}
